import {privateLiveEvent} from '../modules/insight/personal-events.js';
import {authenticate} from './middleware/auth.js';
import {canSeeActivity,publicActivity} from '../modules/insight/activity.js';
export function liveRequest(ctx,source) {
  const current={headers:source.headers,method:'GET'};
  let failure;
  authenticate(ctx)(current,null,error=>{failure=error;});
  if(failure||!current.user)return null;
  try {
    ctx.permissions.scope(current,'insight:read');
    if(source.query.orgId)ctx.permissions.assertOrg(current,source.query.orgId,'org:read');
    if(source.query.projectId)ctx.permissions.assertProject(current,source.query.projectId,'insight:read');
    return current;
  } catch { return null; }
}
export function registerSse(ctx) {
  const connections=new Set();
  ctx.sseRegistered=true;
  ctx.app.get('/api/v1/events',ctx.requireAuth,(req,res)=>{
    ctx.permissions.scope(req,'insight:read');
    if(req.query.orgId)ctx.permissions.assertOrg(req,req.query.orgId,'org:read');
    if(req.query.projectId)ctx.permissions.assertProject(req,req.query.projectId,'insight:read');
    res.status(200).set({'Content-Type':'text/event-stream','Cache-Control':'no-cache, no-store','Connection':'keep-alive','X-Accel-Buffering':'no'});
    res.flushHeaders();
    let closed=false,unsubscribe=()=>{},timer;
    const close=()=>{
      if(closed)return;
      closed=true;clearInterval(timer);unsubscribe();connections.delete(close);
      req.off('close',close);res.off('error',close);res.off('close',close);
      if(!res.writableEnded)res.end();
    };
    const write=(event,data,id)=>{
      if(closed||res.destroyed)return close();
      const frame=(id?'id: '+id+'\n':'')+'event: '+event+'\ndata: '+JSON.stringify(data)+'\n\n';
      if(!res.write(frame))close();
    };
    const delivery=row=>{
      const current=liveRequest(ctx,req);
      if(!current){close();return;}
      if(!row||!canSeeActivity(ctx,current.user.id,row))return;
      if(req.query.orgId&&row.org_id!==req.query.orgId)return;
      if(req.query.projectId&&row.project_id!==req.query.projectId)return;
      write('activity',publicActivity(row),row.id);
    };
    unsubscribe=ctx.bus.subscribe(event=>{
      const current=liveRequest(ctx,req);
      if(!current){close();return;}
      const personal=privateLiveEvent(ctx,current,event);
      if(personal&&(!req.query.orgId||personal.orgId===req.query.orgId)&&(!req.query.projectId||personal.projectId===req.query.projectId))write('inbox',personal);
      delivery(ctx.db.prepare('SELECT * FROM activity WHERE id=?').get(event.id));
    });
    connections.add(close);
    req.on('close',close);res.on('error',close);res.on('close',close);
    write('ready',{userId:req.user.id,time:ctx.now()});
    const last=req.headers['last-event-id']??req.query.lastEventId;
    if(last){
      const anchor=ctx.db.prepare('SELECT * FROM activity WHERE id=?').get(last);
      if(anchor&&canSeeActivity(ctx,req.user.id,anchor)){
        const rows=ctx.db.prepare('SELECT * FROM activity WHERE created_at>? OR (created_at=? AND id>?) ORDER BY created_at,id').all(anchor.created_at,anchor.created_at,anchor.id)
          .filter(row=>canSeeActivity(ctx,req.user.id,row))
          .filter(row=>!req.query.orgId||row.org_id===req.query.orgId)
          .filter(row=>!req.query.projectId||row.project_id===req.query.projectId).slice(0,201);
        if(rows.length>200)write('reset',{reason:'Refresh the activity feed to load missed updates'});
        else for(const row of rows)delivery(row);
      }else write('reset',{reason:'Refresh the activity feed to resume'});
    }
    if(closed)return;
    timer=setInterval(()=>{
      if(!liveRequest(ctx,req))close();
      else write('heartbeat',{time:ctx.now()});
    },15000);
    timer.unref();
  });
  (ctx.cleanups??=[]).push(()=>{for(const close of [...connections])close();});
}

import {emitPersonal} from './personal-events.js';
import {AppError,fields,validation} from '@crew/shared';
import {publicNotification,notificationRows,preferences} from './notifications.js';
export function digestSummary(items) {
  return items.map(item=>{
    const event=item.activity,entity=event.after??event.before??{};
    return [event.time,entity.key??entity.title??entity.name??event.entityType,event.action,item.reason].join(' — ');
  }).join('\n');
}
export function createDigest(ctx,req,orgId) {
  ctx.permissions.assertSelf(req,req.user.id,'insight:write');
  ctx.permissions.assertOrg(req,orgId,'org:read');
  if(!preferences(ctx,req.user.id,orgId).emailEnabled)throw new AppError('CONFLICT','Email digests are disabled in your preferences',409);
  const rows=notificationRows(ctx,req.user.id,{orgId,state:'unread'}).filter(row=>!row.digested_at).slice(0,200);
  if(!rows.length)return {digest:null,count:0,remaining:0};
  const items=rows.map(row=>publicNotification(ctx,row));
  const user=ctx.db.prepare('SELECT email FROM users WHERE id=?').get(req.user.id);
  const digest=ctx.transaction(()=>{
    const result=ctx.enqueueOutbox({orgId,userId:req.user.id,kind:'digest',toEmail:user.email,
      subject:'Crew: '+rows.length+' unread updates',textBody:digestSummary(items),
      payload:{notificationIds:rows.map(row=>row.id),count:rows.length}});
    for(const row of rows)ctx.db.prepare('UPDATE notifications SET digested_at=? WHERE id=? AND user_id=?').run(result.createdAt,row.id,req.user.id);
    return result;
  });
  emitPersonal(ctx,req,{orgId,entityType:'digest',entityId:digest.id,action:'queued',after:{count:rows.length}});
  return {digest:{id:digest.id,orgId,count:rows.length,createdAt:digest.createdAt,items},count:rows.length,
    remaining:notificationRows(ctx,req.user.id,{orgId,state:'unread'}).filter(row=>!row.digested_at).length};
}
export function registerDigestRoutes(ctx) {
  const {app,requireAuth,permissions:p}=ctx;
  app.post('/api/v1/digests',requireAuth,(req,res)=>{
    fields(req.body,['orgId']);if(typeof req.body.orgId!=='string')throw validation({orgId:'Choose an organization'});
    const result=createDigest(ctx,req,req.body.orgId);res.status(result.digest?201:200).json(result);
  });
  app.get('/api/v1/digests',requireAuth,(req,res)=>{
    p.assertSelf(req,req.user.id,'insight:read');
    if(req.query.orgId)p.assertOrg(req,req.query.orgId,'org:read');
    const visible=new Map(notificationRows(ctx,req.user.id,{orgId:req.query.orgId}).map(row=>[row.id,row]));
    const rows=ctx.db.prepare("SELECT * FROM outbox WHERE user_id=? AND kind='digest' ORDER BY created_at DESC,id").all(req.user.id)
      .filter(row=>!req.query.orgId||row.org_id===req.query.orgId)
      .filter(row=>p.membership(req.user.id,row.org_id))
      .map(row=>{
        const payload=JSON.parse(row.payload_json),items=(payload.notificationIds??[]).map(id=>visible.get(id)).filter(Boolean).map(item=>publicNotification(ctx,item));
        return {id:row.id,orgId:row.org_id,createdAt:row.created_at,count:items.length,items,textBody:digestSummary(items)};
      });
    res.json(ctx.paginate(rows,req.query));
  });
}

import {emitPersonal} from './personal-events.js';
import {AppError,validation,fields,uniqueIds} from '@crew/shared';
import {publicActivity,canSeeActivity} from './activity.js';
import {automaticSubscriptions,canReadProject} from './subscriptions.js';
export function preferences(ctx,userId,orgId) {
  const row=ctx.db.prepare('SELECT * FROM notification_preferences WHERE user_id=? AND org_id=?').get(userId,orgId);
  return {orgId,emailEnabled:row?Boolean(row.email_enabled):true,mentionsOnly:row?Boolean(row.mentions_only):false};
}
export function publicNotification(ctx,row) {
  const event=ctx.db.prepare('SELECT * FROM activity WHERE id=?').get(row.activity_id);
  return {id:row.id,orgId:row.org_id,projectId:row.project_id,reason:row.reason,
    readAt:row.read_at,read:Boolean(row.read_at),isRead:Boolean(row.read_at),createdAt:row.created_at,
    activity:publicActivity(event)};
}
export function notificationRows(ctx,userId,query={}) {
  if(query.state&&!['all','unread','read'].includes(query.state))throw validation({state:'Choose all, unread or read'});
  return ctx.db.prepare('SELECT n.* FROM notifications n WHERE n.user_id=? ORDER BY n.created_at DESC,n.id DESC').all(userId)
    .filter(row=>!query.orgId||row.org_id===query.orgId)
    .filter(row=>!query.projectId||row.project_id===query.projectId)
    .filter(row=>query.state==='read'?Boolean(row.read_at):query.state==='unread'?!row.read_at:true)
    .filter(row=>canReadProject(ctx,userId,row.project_id))
    .filter(row=>canSeeActivity(ctx,userId,ctx.db.prepare('SELECT * FROM activity WHERE id=?').get(row.activity_id)));
}
export function notifyActivity(ctx,event,activity) {
  const {issueId,mentioned}=automaticSubscriptions(ctx,event);
  if(!event.projectId||!activity)return;
  const watchers=ctx.db.prepare(`SELECT * FROM subscriptions WHERE project_id=? AND reason<>'muted'
    AND ((target_type='project' AND target_id=?) OR (target_type='issue' AND target_id=?))`).all(event.projectId,event.projectId,issueId??'');
  const users=new Map(watchers.map(row=>[row.user_id,'watching']));
  for(const userId of mentioned)users.set(userId,'mention');
  const after=event.after;
  if(event.entityType==='issue'&&after?.assigneeId&&after.assigneeId!==event.before?.assigneeId)users.set(after.assigneeId,'assignment');
  for(const [userId,reason] of users) {
    if(userId===event.actorId||!canReadProject(ctx,userId,event.projectId))continue;
    if(preferences(ctx,userId,event.orgId).mentionsOnly&&reason!=='mention')continue;
    const row=ctx.db.prepare('SELECT * FROM activity WHERE id=?').get(activity.id);
    if(!canSeeActivity(ctx,userId,row))continue;
    ctx.db.prepare(`INSERT OR IGNORE INTO notifications
      (id,user_id,org_id,project_id,activity_id,reason,created_at) VALUES (?,?,?,?,?,?,?)`)
      .run(ctx.id(),userId,event.orgId,event.projectId,event.id,reason,event.time);
  }
}
export function registerNotificationRoutes(ctx) {
  const {app,requireAuth,permissions:p}=ctx;
  app.get('/api/v1/notifications',requireAuth,(req,res)=>{
    p.assertSelf(req,req.user.id,'insight:read');
    if(req.query.orgId)p.assertOrg(req,req.query.orgId,'org:read');
    if(req.query.projectId)p.assertProject(req,req.query.projectId,'insight:read');
    const rows=notificationRows(ctx,req.user.id,req.query);
    const all=notificationRows(ctx,req.user.id,{orgId:req.query.orgId,projectId:req.query.projectId});
    res.json({...ctx.paginate(rows.map(row=>publicNotification(ctx,row)),req.query),unread:all.filter(row=>!row.read_at).length});
  });
  app.patch('/api/v1/notifications/:notificationId',requireAuth,(req,res)=>{
    p.assertSelf(req,req.user.id,'insight:write');fields(req.body,['read']);
    if(typeof req.body.read!=='boolean')throw validation({read:'Expected true or false'});
    const row=notificationRows(ctx,req.user.id).find(item=>item.id===req.params.notificationId);
    if(!row)throw new AppError('NOT_FOUND','Notification not found',404);
    ctx.db.prepare('UPDATE notifications SET read_at=? WHERE id=? AND user_id=?').run(req.body.read?ctx.now():null,row.id,req.user.id);
    emitPersonal(ctx,req,{orgId:row.org_id,projectId:row.project_id,entityType:'notification',entityId:row.id,action:req.body.read?'read':'unread',before:{read:Boolean(row.read_at)},after:{read:req.body.read}});
    res.json({notification:publicNotification(ctx,ctx.db.prepare('SELECT * FROM notifications WHERE id=?').get(row.id))});
  });
  app.post('/api/v1/notifications/mark',requireAuth,(req,res)=>{
    p.assertSelf(req,req.user.id,'insight:write');fields(req.body,['ids','all','orgId','read']);
    if(typeof req.body.read!=='boolean')throw validation({read:'Expected true or false'});
    if(req.body.orgId)p.assertOrg(req,req.body.orgId,'org:read');
    if(req.body.all!==true&&req.body.ids===undefined)throw validation({ids:'Select notification ids or all=true'});
    if(req.body.all===true&&req.body.ids!==undefined)throw validation({ids:'Use ids or all, not both'});
    const ids=req.body.all===true?null:new Set(uniqueIds(req.body.ids,'ids',{max:200}));
    const visible=notificationRows(ctx,req.user.id,{orgId:req.body.orgId});
    if(ids&&[...ids].some(id=>!visible.some(row=>row.id===id)))throw validation({ids:'Every notification must belong to your visible inbox'});
    const rows=visible.filter(row=>!ids||ids.has(row.id)),readAt=req.body.read?ctx.now():null;
    ctx.transaction(()=>{for(const row of rows)ctx.db.prepare('UPDATE notifications SET read_at=? WHERE id=? AND user_id=?').run(readAt,row.id,req.user.id);});
    for(const row of rows)emitPersonal(ctx,req,{orgId:row.org_id,projectId:row.project_id,entityType:'notification',entityId:row.id,action:req.body.read?'read':'unread',after:{read:req.body.read}});
    res.json({changed:rows.length,read:req.body.read});
  });
  app.get('/api/v1/notification-preferences',requireAuth,(req,res)=>{
    p.assertSelf(req,req.user.id,'insight:read');p.assertOrg(req,req.query.orgId,'org:read');
    res.json({preferences:preferences(ctx,req.user.id,req.query.orgId)});
  });
  app.patch('/api/v1/notification-preferences',requireAuth,(req,res)=>{
    p.assertSelf(req,req.user.id,'insight:write');fields(req.body,['orgId','emailEnabled','mentionsOnly']);p.assertOrg(req,req.body.orgId,'org:read');
    const current=preferences(ctx,req.user.id,req.body.orgId);
    for(const key of ['emailEnabled','mentionsOnly'])if(req.body[key]!==undefined&&typeof req.body[key]!=='boolean')throw validation({[key]:'Expected true or false'});
    const next={...current,...req.body};
    ctx.db.prepare(`INSERT INTO notification_preferences VALUES (?,?,?,?,?) ON CONFLICT(user_id,org_id)
      DO UPDATE SET email_enabled=excluded.email_enabled,mentions_only=excluded.mentions_only,updated_at=excluded.updated_at`)
      .run(req.user.id,next.orgId,Number(next.emailEnabled),Number(next.mentionsOnly),ctx.now());
    emitPersonal(ctx,req,{orgId:next.orgId,entityType:'notificationPreference',entityId:req.user.id,action:'updated',before:current,after:next});
    res.json({preferences:preferences(ctx,req.user.id,next.orgId)});
  });
}

export function emitPersonal(ctx,req,{orgId,projectId=null,entityType,entityId,action,before=null,after=null}) {
  return ctx.bus.emit({actorId:req.user.id,userId:req.user.id,orgId,projectId,entityType,entityId,action,before,after,time:ctx.now()});
}
export function privateLiveEvent(ctx,req,event) {
  if(!['notification','subscription','notificationPreference','digest'].includes(event.entityType))return null;
  if(event.userId!==req.user.id)return null;
  if(!event.orgId||!ctx.permissions.membership(req.user.id,event.orgId))return null;
  if(event.projectId) {
    try{if(!ctx.permissions.canProject(req.user.id,event.projectId,'insight:read'))return null;}
    catch(error){if(error.code==='NOT_FOUND')return null;throw error;}
  }
  return {orgId:event.orgId,projectId:event.projectId,entityType:event.entityType,entityId:event.entityId,action:event.action,time:event.time};
}

import {emitPersonal} from './personal-events.js';
import {validation,fields,choice,text} from '@crew/shared';
import {getIssue} from '../work/issues.js';
export function subscriptionTarget(ctx,req,type,targetId,permission='insight:read') {
  if (!['issue','project'].includes(type)) throw validation({targetType:'Choose issue or project'});
  const issue = type==='issue'?getIssue(ctx,targetId):null;
  const project = ctx.permissions.assertProject(req,issue?.projectId??targetId,permission);
  return {type,targetId,projectId:project.id,orgId:project.org_id,issue};
}
export function publicSubscription(row) {
  return {userId:row.user_id,orgId:row.org_id,projectId:row.project_id,targetType:row.target_type,
    targetId:row.target_id,manual:Boolean(row.manual),reason:row.reason,createdAt:row.created_at};
}
export function canReadProject(ctx,userId,projectId) {
  try { return ctx.permissions.canProject(userId,projectId,'insight:read'); }
  catch(error) { if(error.code==='NOT_FOUND')return false;throw error; }
}
export function subscribe(ctx,userId,target,reason='watch',manual=false) {
  if(!userId || !canReadProject(ctx,userId,target.projectId))return false;
  const existing=ctx.db.prepare('SELECT * FROM subscriptions WHERE user_id=? AND target_type=? AND target_id=?').get(userId,target.type,target.targetId);
  if(existing?.reason==='muted'&&!manual)return false;
  ctx.db.prepare(`INSERT INTO subscriptions(user_id,org_id,project_id,target_type,target_id,manual,reason,created_at)
    VALUES (?,?,?,?,?,?,?,?) ON CONFLICT(user_id,target_type,target_id) DO UPDATE SET
    manual=MAX(manual,excluded.manual),reason=CASE WHEN excluded.manual=1 THEN 'watch' ELSE subscriptions.reason END`)
    .run(userId,target.orgId,target.projectId,target.type,target.targetId,Number(manual),reason,ctx.now());
  return true;
}
export function automaticSubscriptions(ctx,event) {
  const item=event.after??event.before;
  const issue=event.entityType==='issue'?item:item?.issue;
  const issueId=issue?.id??event.issueId??item?.issueId;
  if(!event.projectId||!issueId)return {issueId:null,mentioned:[]};
  const target={type:'issue',targetId:issueId,orgId:event.orgId,projectId:event.projectId};
  if(issue) {
    subscribe(ctx,issue.createdBy,target,'creator');
    subscribe(ctx,issue.assigneeId,target,'assignee');
  }
  const mentioned=[...new Set([...(event.mentionedUserIds??[]),...(event.after?.mentionedUserIds??[]),...(event.after?.userIds??[])])];
  for(const userId of mentioned)subscribe(ctx,userId,target,'mention');
  return {issueId,mentioned};
}
export function registerSubscriptionRoutes(ctx) {
  const {app,requireAuth,permissions:p}=ctx;
  app.get('/api/v1/subscriptions',requireAuth,(req,res)=>{
    p.assertSelf(req,req.user.id,'insight:read');
    if(req.query.orgId)p.assertOrg(req,req.query.orgId,'org:read');
    const rows=ctx.db.prepare("SELECT * FROM subscriptions WHERE user_id=? AND reason<>'muted' ORDER BY created_at DESC,target_id").all(req.user.id)
      .filter(row=>!req.query.orgId||row.org_id===req.query.orgId)
      .filter(row=>!req.query.projectId||row.project_id===req.query.projectId)
      .filter(row=>!req.query.targetType||row.target_type===req.query.targetType)
      .filter(row=>!req.query.targetId||row.target_id===req.query.targetId)
      .filter(row=>row.target_type!=='issue'||ctx.db.prepare('SELECT 1 FROM issues WHERE id=?').get(row.target_id))
      .filter(row=>canReadProject(ctx,req.user.id,row.project_id))
      .map(row=>{
        const target=row.target_type==='issue'?getIssue(ctx,row.target_id):ctx.db.prepare('SELECT * FROM projects WHERE id=?').get(row.target_id);
        const label=row.target_type==='issue'?target.key+' · '+target.title:target.key+' · '+target.name;
        return {...publicSubscription(row),id:row.target_type+':'+row.target_id,target:{id:row.target_id,label}};
      });
    res.json(ctx.paginate(rows,req.query));
  });
  app.post('/api/v1/subscriptions',requireAuth,(req,res)=>{
    p.assertSelf(req,req.user.id,'insight:write');
    fields(req.body,['targetType','targetId']);
    const type=choice(req.body.targetType,'targetType',['issue','project']);
    const targetId=text(req.body.targetId,'targetId',{max:128});
    const target=subscriptionTarget(ctx,req,type,targetId);
    const existing=ctx.db.prepare('SELECT 1 FROM subscriptions WHERE user_id=? AND target_type=? AND target_id=?').get(req.user.id,type,targetId);
    if(existing)ctx.db.prepare("UPDATE subscriptions SET manual=1,reason='watch' WHERE user_id=? AND target_type=? AND target_id=?").run(req.user.id,type,targetId);
    else subscribe(ctx,req.user.id,target,'watch',true);
    const row=ctx.db.prepare('SELECT * FROM subscriptions WHERE user_id=? AND target_type=? AND target_id=?').get(req.user.id,type,targetId);
    emitPersonal(ctx,req,{orgId:target.orgId,projectId:target.projectId,entityType:'subscription',entityId:type+':'+targetId,action:'watched'});
    res.status(201).json({subscription:publicSubscription(row)});
  });
  app.delete('/api/v1/subscriptions/:targetType/:targetId',requireAuth,(req,res)=>{
    p.assertSelf(req,req.user.id,'insight:write');
    const target=subscriptionTarget(ctx,req,req.params.targetType,req.params.targetId);
    subscribe(ctx,req.user.id,target,'muted',true);
    ctx.db.prepare("UPDATE subscriptions SET manual=0,reason='muted' WHERE user_id=? AND target_type=? AND target_id=?").run(req.user.id,target.type,target.targetId);
    emitPersonal(ctx,req,{orgId:target.orgId,projectId:target.projectId,entityType:'subscription',entityId:target.type+':'+target.targetId,action:'muted'});
    res.json({ok:true});
  });
}

import {useEffect,useRef,useState} from 'preact/hooks';
export function liveUrl({orgId,projectId}={}) {
  const query=new URLSearchParams();
  if(orgId)query.set('orgId',orgId);
  if(projectId)query.set('projectId',projectId);
  return '/api/v1/events'+(query.size?'?'+query:'');
}
export function connectLive({orgId,projectId,onActivity=()=>{},onStatus=()=>{},onReset=()=>{},EventSourceClass=globalThis.EventSource}={}) {
  if(!EventSourceClass){onStatus('unavailable');return ()=>{};}
  let active=true;
  const source=new EventSourceClass(liveUrl({orgId,projectId}),{withCredentials:true});
  onStatus('connecting');
  const parse=callback=>event=>{
    if(!active)return;
    try {callback(JSON.parse(event.data));}
    catch(error){onStatus('invalid update');}
  };
  source.addEventListener('ready',()=>{if(active){onStatus('live');onReset({reason:'connected'});}});
  source.addEventListener('activity',parse(onActivity));
  source.addEventListener('inbox',parse(onActivity));
  source.addEventListener('reset',parse(onReset));
  source.addEventListener('error',()=>active&&onStatus(source.readyState===2?'closed':'reconnecting'));
  return ()=>{if(active){active=false;source.close();onStatus('paused');}};
}
export function useLiveUpdates({orgId,projectId,onActivity,enabled=true}={}) {
  const callback=useRef(onActivity);
  callback.current=onActivity;
  const [paused,setPaused]=useState(false);
  const [status,setStatus]=useState('paused');
  const [lastEventAt,setLastEventAt]=useState(null);
  useEffect(()=>{
    if(!enabled||paused){setStatus('paused');return;}
    return connectLive({orgId,projectId,onStatus:setStatus,
      onActivity:event=>{setLastEventAt(event.time);callback.current?.(event);},
      onReset:()=>callback.current?.({action:'refresh'})});
  },[orgId,projectId,enabled,paused]);
  return {status,paused,setPaused,lastEventAt};
}
